         val launch = packageManager.getLaunchIntentForPackage(packageName)
         val contentIntent = if (launch != null) {
             PendingIntent.getActivity(
                 this,
                 0,
                 launch,
                 PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
