```kotlin
override fun onRenderProcessGone(view: WebView, detail: RenderProcessGoneDetail): Boolean {
    // Рендер-процесс WebView упал: без обработки система убивает приложение,
    // а вью остаётся пустой (виден только фон). Удаляем мёртвую вью из пула
    // и пересоздаём вкладку — страница снова грузится.
    val deadUrl = runCatching { view.url }.getOrNull() ?: urlState.value
    webViewPool.entries.removeAll { it.value === view }
    runCatching { (view.parent as? ViewGroup)?.removeView(view) }
    runCatching { view.destroy() }
    if (sharedWebView === view) sharedWebView = null
    canGoBackState.value = false
    canGoForwardState.value = false
    runCatching {
        android.os.Handler(android.os.Looper.getMainLooper()).post {
            view.context.toast(if (detail.didCrash()) "WebView упал — перезапускаю страницу" else "WebView выгружен — перезапускаю страницу")
        }
    }
    // Заставляем AndroidView пересоздать вью и загрузить адрес заново.
    lastCrashUrl = deadUrl
    rendererEpoch.value++
    return true
}
