Now I'll add injection of user scripts (from WebScriptsStore) in onPageStarted/onPageFinished, and add the extensions UI. Let me first build the WebScripts store and dialog files, then wire in.

Let me write `WebScripts.kt`.

Design:

```kotlin
package eu.kanade.tachiyomi.ui.webbrowser

import android.content.Context
import android.webkit.WebView
import kotlinx.coroutines.flow.MutableStateFlow
import org.json.JSONArray
import org.json.JSONObject
import java.io.File

object WebScriptsStore {
    data class UserScript(
        val id: String,
        val name: String,
        val match: String,
        val code: String,
        val enabled: Boolean,
        val runAt: String, // "start" | "end"
    )

    val scripts = MutableStateFlow<List<UserScript>>(emptyList())
    private var loaded = false

    private fun file(context: Context) = File(context.filesDir, "webscripts.json")

    @Synchronized
    fun load(context: Context) {
        if (loaded) return
        loaded = true
        runCatching {
            val f = file(context)
            if (!f.isFile) return@runCatching
            val arr = JSONArray(f.readText())
            scripts.value = (0 until arr.length()).mapNotNull { i ->
                runCatching {
                    val o = arr.getJSONObject(i)
                    UserScript(
                        o.optString("id"),
                        o.optString("name"),
                        o.optString("match", "*"),
                        o.optString("code"),
                        o.optBoolean("enabled", true),
                        o.optString("runAt", "end"),
                    )
                }.getOrNull()
            }
        }
    }

    private fun save(context: Context) {
        runCatching {
            val arr = JSONArray()
            scripts.value.forEach { s ->
                arr.put(JSONObject().apply {
                    put("id", s.id); put("name", s.name); put("match", s.match)
                    put("code", s.code); put("enabled", s.enabled); put("runAt", s.runAt)
                })
            }
            file(context).writeText(arr.toString())
        }
    }

    fun add(context, name, match, code, runAt): UserScript {
        load(context)
        val s = UserScript(System.currentTimeMillis().toString(), name.ifBlank{"Скрипт"}, match.ifBlank{"*"}, code, true, runAt)
        scripts.value = scripts.value + s
        save(context)
        return s
    }
    fun update(context, s: UserScript) { load; scripts.value = scripts.value.map { if (it.id==s.id) s else it }; save }
    fun remove(context, id) { load; scripts.value = scripts.value.filterNot{it.id==id}; save }
    fun setEnabled(context, id, enabled) { ... }
    fun toggle(context, id, enabled) ...

    /** Совпадает ли url со шаблоном match. Поддерживает '*' и '|' / переносы. */
    fun matches(match: String, url: String): Boolean {
        val patterns = match.split('\n', ',').map{it.trim()}.filter{it.isNotEmpty()}
        if (patterns.isEmpty()) return true
        return patterns.any { pat ->
            if (pat == "*") return true
            val re = ".*" is wildcard...
            Regex("^" + Regex.escape(pat).replace("\\*", ".*") + "$").matches(url)
        }
    }
    ...
```
Wait `Regex.escape` escapes `*` to `\*`? In Kotlin, `Regex.escape` escapes all metacharacters. Then replacing "\\*" won't work because escape output for `*` is `\*` — actually `Regex.escape("*")` returns "\\*"? Let me not rely on that. I'll build regex manually by splitting on '*'.

```kotlin
fun matches(match: String, url: String): Boolean {
    val u = url.lowercase()
    val pats = match.split('\n', ',').map { it.trim() }.filter { it.isNotEmpty() }
    if (pats.isEmpty()) return true
    return pats.any { p ->
        val lp = p.lowercase()
        if (lp == "*" || lp == "all") return true
        val re = lp.split('*').joinToString(".*") { Regex.escape(it) }
        Regex("^$re$").containsMatchIn(u)
    }
}
```
Good.

Injection:
```kotlin
fun inject(context: Context, view: WebView?, url: String?, runAt: String) {
    val wv = view ?: return
    val u = url ?: return
    load(context)
    val at = if (runAt == "start") "start" else "end"
    scripts.value
        .filter { it.enabled && it.runAt == at && matches(it.match, u) }
        .forEach { s ->
            val wrapped = "try{" + s.code + "\n}catch(e){console.warn('yk-script '+e);}"
            runCatching { wv.evaluateJavascript(wrapped, null) }
        }
}

/** Переинжектить все подходящие скрипты в текущую страницу (после правки). */
fun injectAll(context: Context, view: WebView?, url: String?) {
    inject(context, view, url, "start")
    inject(context, view, url, "end")
}
```

