private suspend fun scanWithTextEngine(
    chapterId: Long,
    pageIndex: Int,
    image: Bitmap,
    type: EngineType,
): OcrPageResult {
    val text = recognizeWithEngine(type, image).trim()
    val model = when (type) {
        EngineType.OPENROUTER -> OcrModel.OPENROUTER
        EngineType.GOOGLE -> OcrModel.GOOGLE
        else -> error("Unsupported text-only OCR engine: $type")
    }
    val regions = if (text.isBlank()) {
        emptyList()
    } else {
        listOf(
            OcrRegion(
                order = 0,
                text = text,
                boundingBox = OcrBoundingBox(0f, 0f, 1f, 1f),
                textOrientation = OcrTextOrientation.Horizontal,
            ),
        )
    }
    return OcrPageResult(
        chapterId = chapterId,
        pageIndex = pageIndex,
        ocrModel = model,
        imageWidth = image.width,
        imageHeight = image.height,
        regions = regions,
    )
}

private suspend fun scanWithZenFree(
    chapterId: Long,
    pageIndex: Int,
    image: Bitmap,
): OcrPageResult {
    val recognized = submitTask(PrioritizedTaskQueue.Priority.NORMAL) {
        engineLocks.withTextEngineLock(EngineType.ZEN_FREE) {
            val engine = engineFor(EngineType.ZEN_FREE)
            if (engine is ZenFreeOcrEngine) engine.recognizePage(image) else emptyList()
        }
    }
    val regions = recognized.mapIndexedNotNull { index, region ->
        val text = OcrTextCleaner.joinLineHyphens(region.text).trim()
        text.takeIf(String::isNotEmpty)?.let {
            region.copy(order = index, text = it)
        }
    }
    return OcrPageResult(
        chapterId = chapterId,
        pageIndex = pageIndex,
        ocrModel = OcrModel.ZEN_FREE,
        imageWidth = image.width,
        imageHeight = image.height,
        regions = regions,
    )
}

/**
 * Распознавание через вкомпилированную модель Google ML Kit.
 *
 * ML Kit отдаёт готовые строки с координатами, поэтому отдельный детектор
 * не нужен: каждая строка становится регионом, и тап по реплике открывает
 * именно её. Если движок падает или ничего не нашёл — честно уходим в общий
 * фолбэк (онлайн Glens при сети, иначе локальный кириллический PP-OCR).
 */
private suspend fun scanWithMlKit(
    chapterId: Long,
    pageIndex: Int,
    image: Bitmap,
    modelKey: OcrModel,
    onPartial: ((OcrRegion) -> Unit)? = null,
): OcrPageResult {
    val regions = submitTask(PrioritizedTaskQueue.Priority.NORMAL) {
        engineLocks.withTextEngineLock(EngineType.MLKIT) {
            val engine = engineFor(EngineType.MLKIT)
            if (engine is MlKitOcrEngine) engine.recognizeRegions(image) else emptyList()
        }
    }

    val mapped = regions.mapIndexedNotNull { index, region ->
        val text = OcrTextCleaner.joinLineHyphens(region.text).trim()
        text.takeIf { it.isNotBlank() }?.let {
            OcrRegion(
                order = index,
                text = it,
                boundingBox = region.boundingBox,
                textOrientation = OcrTextOrientation.Horizontal,
            )
        }
    }
    // Прогресс по мере готовности: движок уже вернул все области, но
    // авточтение может начать читать их, не дожидаясь сборки страницы.
    mapped.forEach { region -> onPartial?.invoke(region) }

    if (mapped.isEmpty()) {
        return OcrPageResult(
            chapterId = chapterId,
            pageIndex = pageIndex,
            ocrModel = modelKey,
            imageWidth = image.width,
            imageHeight = image.height,
            regions = emptyList(),
        )
    }

    return OcrPageResult(
        chapterId = chapterId,
        pageIndex = pageIndex,
        ocrModel = modelKey,
        imageWidth = image.width,
        imageHeight = image.height,
        regions = mapped,
    )
}

private suspend fun scanWithGlens(
    chapterId: Long,
    pageIndex: Int,
    image: Bitmap,
    modelKey: OcrModel,
): OcrPageResult {
    val result = try {
        submitTask(PrioritizedTaskQueue.Priority.NORMAL) {
            engineLocks.withTextEngineLock(EngineType.GLENS) {
                glensEngine().recognizePage(image)
            }
        }
    } catch (error: Throwable) {
        if (error is CancellationException) throw error
        if (isConnectivityFailure(error)) {
            throw OcrException.ConnectionError(error)
        }
        throw error
    }
    return OcrPageResult(
        chapterId = chapterId,
        pageIndex = pageIndex,
        ocrModel = modelKey,
        imageWidth = image.width,
        imageHeight = image.height,
        regions = result.regions.map { it.copy(text = OcrTextCleaner.joinLineHyphens(it.text)) },
    )
}

private suspend fun scanWithOwOcr(
    chapterId: Long,
    pageIndex: Int,
    image: Bitmap,
    modelKey: OcrModel,
): OcrPageResult {
    val result = try {
        submitTask(PrioritizedTaskQueue.Priority.NORMAL) {
            engineLocks.withTextEngineLock(EngineType.OWOCR) {
                val engine = owOcrEngine ?: OwOcrEngine(context).also {
                    owOcrEngine = it
                }
                engine.recognizePage(image)
            }
        }
    } catch (error: Throwable) {
        if (error is CancellationException) throw error
        if (isConnectivityFailure(error)) {
            throw OcrException.ConnectionError(error)
        }
        throw error
    }
    return OcrPageResult(
        chapterId = chapterId,
        pageIndex = pageIndex,
        ocrModel = modelKey,
        imageWidth = image.width,
        imageHeight = image.height,
        regions = result.map { it.copy(text = OcrTextCleaner.joinLineHyphens(it.text)) },
    )
}

private suspend fun scanLocally(
    chapterId: Long,
    pageIndex: Int,
    image: Bitmap,
    modelKey: OcrModel,
    type: EngineType,
    onPartial: ((OcrRegion) -> Unit)? = null,
): OcrPageResult {
    // Детектор областей работает на модели PP-OCRv4 из пака cyrillic_ocr
    // и даёт по региону на строку — благодаря этому тап по конкретной
    // реплике открывает именно её.
    //
    // Если пак не установлен (или LiteRT недоступен), детектор бросает
    // DetectionUnavailable, и мы честно деградируем: распознаём страницу
    // целиком и отдаём один регион на весь лист (isWholePage = true).
    // Раньше заглушка бросала всегда, поэтому постраничный режим был
    // единственно возможным.
    val boxes: List<OcrBoundingBox>? = try {
        submitTask(PrioritizedTaskQueue.Priority.NORMAL) {
            engineLocks.withDetectionLock {
                val engine = detectionEngine()
                engine.detectTextRegions(image)
            }
        }
            .filter(OcrBoundingBox::isValid)
    } catch (e: OcrException.DetectionUnavailable) {
        logcat(LogPriority.INFO) {
            "Region detector unavailable; falling back to whole-page recognition"
        }
        null
    }

    // Детектор ничего не нашёл, либо нашёл единственный бокс во весь лист:
    // разметки по репликам не получится, поэтому идём общим путём, а не
    // сообщаем «текста нет».
    val usableBoxes = boxes?.takeIf { found ->
        found.isNotEmpty() && !(found.size == 1 && OcrBoxGeometry.coversWholePage(found[0]))
    }

    if (usableBoxes == null) {
        val text = submitTask(PrioritizedTaskQueue.Priority.NORMAL) {
            recognizeWithEngine(type, image)
        }.trim()
        val regions = if (text.isBlank()) {
            emptyList()
        } else {
            val region = OcrRegion(
                order = 0,
                text = text,
                boundingBox = OcrBoundingBox(0f, 0f, 1f, 1f),
                textOrientation = OcrTextOrientation.Horizontal,
            )
            onPartial?.invoke(region)
            listOf(region)
        }
        return OcrPageResult(
            chapterId = chapterId,
            pageIndex = pageIndex,
            ocrModel = modelKey,
            imageWidth = image.width,
            imageHeight = image.height,
            regions = regions,
        )
    }

    val regions = mutableListOf<OcrRegion>()
    // Области обрабатываются СТРОГО ПО ОЧЕРЕДИ, и каждая готовая реплика
    // сразу уходит в onPartial. Раньше цикл был ленивым mapIndexedNotNull,
    // который копил всё до конца: читатель ждал последнюю реплику страницы,
    // чтобы услышать первую. Теперь озвучка идёт вслед за распознаванием.
    for ((index, box) in usableBoxes.withIndex()) {
        val crop = cropBitmap(image, box) ?: continue
        val orientation = if (
            OcrBoxGeometry.classifyKind(0, 0, crop.width, crop.height, crop.width, crop.height) ==
            OcrBoxGeometry.Kind.VERTICAL
        ) {
            OcrTextOrientation.Vertical
        } else {
            OcrTextOrientation.Horizontal
        }
        val text = try {
            submitTask(PrioritizedTaskQueue.Priority.NORMAL) {
                engineLocks.withTextEngineLock(type) {
                    val engine = engineFor(type)
                    if (engine is LineOcrEngine) {
                        // Кроп — уже готовая строка: повторный детектор
                        // запрещён, иначе линия дробится и текст рушится.
                        engine.recognizeLine(crop)
                    } else {
                        engine.recognizeText(crop)
                    }
                }
            }.trim()
        } finally {
            if (!crop.isRecycled) {
                crop.recycle()
            }
        }
        if (text.isBlank()) continue
        val region = OcrRegion(
            order = index,
            text = text,
            boundingBox = box,
            textOrientation = orientation,
        )
        regions += region
        onPartial?.invoke(region)
    }

    // Если детектор нашёл области, но каждая построчная попытка была
    // отклонена, не превращаем видимое большое облачко в «Нет результатов».
    // Выполняем один локальный цельностраничный rescue-проход; он проходит
    // через тот же CyrillicOcrEngine и те же UTF-8/кириллические фильтры.
    val finalRegions = if (regions.isNotEmpty()) {
        regions
    } else {
        val text = submitTask(PrioritizedTaskQueue.Priority.NORMAL) {
            recognizeWithEngine(type, image)
        }.trim()
        if (text.isBlank()) {
            emptyList()
        } else {
            val region = OcrRegion(
                order = 0,
                text = text,
                boundingBox = OcrBoundingBox(0f, 0f, 1f, 1f),
                textOrientation = OcrTextOrientation.Horizontal,
            )
            onPartial?.invoke(region)
            listOf(region)
        }
    }

    return OcrPageResult(
        chapterId = chapterId,
        pageIndex = pageIndex,
        ocrModel = modelKey,
        imageWidth = image.width,
        imageHeight = image.height,
        regions = finalRegions,
    )
}

private fun cropBitmap(
    image: Bitmap,
    box: OcrBoundingBox,
): Bitmap? {
    val left = (box.left * image.width).toInt().coerceIn(0, image.width - 1)
    val top = (box.top * image.height).toInt().coerceIn(0, image.height - 1)
    val right = (box.right * image.width).toInt().coerceIn(left + 1, image.width)
    val bottom = (box.bottom * image.height).toInt().coerceIn(top + 1, image.height)

    val rect = Rect(left, top, right, bottom)
    if (rect.width() <= 0 || rect.height() <= 0) {
        return null
    }

    /**
     * Доминирующий язык текста кадра по письменности: "ru"/"en"/"ja"/"ko"/"zh",
 * "" — букв не нашлось. Нужен, чтобы при источнике «auto» решить, надо ли
 * переводить: эталонный язык реплик из настроек (по умолчанию «ru») врал
 * на китайской манхуа, и перевод молча выключался.
 */
fun dominantLanguage(texts: List<String>): String {
    var cyr = 0
    var lat = 0
    var kana = 0
    var hangul = 0
    var han = 0
    for (t in texts) {
        for (ch in t) {
            when {
                ch in '\u0400'..'\u04FF' -> cyr++
                ch in '\u0041'..'\u005A' || ch in '\u0061'..'\u007A' -> lat++
                ch in '\u3040'..'\u30FF' -> kana++
                ch in '\uAC00'..'\uD7AF' -> hangul++
                ch in '\u4E00'..'\u9FFF' -> han++
            }
        }
    }
    val top = maxOf(cyr, lat, kana, hangul, han)
    if (top == 0) return ""
    return when (top) {
        cyr -> "ru"
        lat -> "en"
        kana -> "ja"
        hangul -> "ko"
        else -> "zh"
    }
}

/**
 * Упорядочивает реплики кадра в читаемом порядке.
     *
     * Раньше реплики сортировались одним ключом: манга — по правому краю
     * (самая правая рамка первой), комикс — по левому, вебтун — по верху.
     * На реальной странице рамки баллонов РАЗНОЙ ширины и высоты (широкий
     * баллон сверху и узкий справа внизу), и одноключевая сортировка
     * читала узкий баллон в центре панели раньше верхнего широкого — «верха
     * пропускает». [ReadingOrderSorter] делит кадр рекурсивным разрезанием:
     *  • горизонтальный разрез — сверху вниз (первично);
     *  • вертикальный разрез — справа налево (манга) / слева направо;
     *  • когда чистого разреза нет (перекрытия вебтуна) — позиционный
     *    фолбэк, где первичен верх, а не правый край.
     * Так верхние реплики всегда читаются раньше нижних в любом вложении.
     */
    fun orderRegions(lines: List<Line>, order: String): List<Line> {
        if (lines.size <= 1) return lines
        val direction = when (order) {
            "ltr" -> tachiyomi.core.common.util.system.ReadingDirection.LTR
            "vertical" -> tachiyomi.core.common.util.system.ReadingDirection.VERTICAL
            else -> tachiyomi.core.common.util.system.ReadingDirection.RTL
        }
        // Рамки хранятся в долях 0..1, а сортировщик работает с целыми
        // Rect: масштабируем на 100000, геометрия и зазоры сохраняются.

        // КОЛОНКИ: махва/лента с блоками разной ширины («одна шире, вторая
        // уже, третья в полэкрана») читается колонка за колонкой — иначе
        // сортировщик прыгал зигзагом между ними. Колонки упорядочиваются
        // по направлению чтения: RTL — справа налево, LTR — слева направо.
        if (order != "vertical") {
            val columns = splitIntoColumns(lines)
            if (columns.size >= 2) {
                val orderedColumns = when (direction) {
                    tachiyomi.core.common.util.system.ReadingDirection.RTL ->
                        columns.sortedByDescending { c -> c.minOf { it.boundingBox.left } }
                    else -> columns.sortedBy { c -> c.minOf { it.boundingBox.left } }
                }
                return orderedColumns.flatMap { column -> orderWithinColumn(column, direction) }
            }
        }

        // Манга и комикс читаются по горизонтальным полосам (строкам реплик),
        // а направление работает ВНУТРИ полосы. Без этого сортировщик при
        // отсутствии чистого разреза выходил на фолбэк «сначала top», и бабл,
        // стоящий на пару процентов выше слева, читался раньше правого —
        // манга уходила в чтение слева направо.
        if (order != "vertical") {
            val bands = groupIntoBands(lines)
            if (bands.size > 1) {
                return bands.flatMap { band -> orderWithinColumn(band, direction) }
            }
        }

        val sortedIndices =
            tachiyomi.core.common.util.system.ReadingOrderSorter.sort(lines.map(::rectOf), direction)
        return sortedIndices.map { lines[it] }
    }

    /** Порядок ВНУТРИ колонки/полосы: сверху вниз, при равных Y — по направлению. */
    private fun orderWithinColumn(
        lines: List<Line>,
        direction: tachiyomi.core.common.util.system.ReadingDirection,
    ): List<Line> {
        val bands = groupIntoBands(lines)
        return bands.flatMap { band ->
            if (band.size == 1) {
                band
            } else {
                tachiyomi.core.common.util.system.ReadingOrderSorter
                    .sort(band.map(::rectOf), direction)
                    .map { band[it] }
            }
        }
    }

    /** Рамка реплики в целых coordenтах для [ReadingOrderSorter]. */
    private fun rectOf(line: Line): android.graphics.Rect = line.boundingBox.let { b ->
