)

data class ReaderPageOcrRegionTap(
    val regionOrder: Int,
    val displayText: String,
    val queryText: String,
    val boundingBox: OcrBoundingBox,
    val textOrientation: OcrTextOrientation,
    val anchorRectOnScreen: RectF?,
