/**
 * Раскладывает рамки текста ПО ПАНЕЛЯМ манги: панели уже пришли в порядке
 * чтения (ReadingOrderSorter в детекторе), внутри панели — свои правила.
 * Без этого баблоны читались в порядке, который вернул детектор, и реплики
 * из соседних панелей перемешивались («верх манги — низ манги»).
 */
internal fun orderBoxesByPanels(
    boxes: List<OcrBoundingBox>,
    panels: List<OcrBoundingBox>,
    direction: ReadingDirection,
): List<OcrBoundingBox> {
    if (boxes.size < 2 || panels.size < 2) return boxes
    val buckets = List(panels.size) { mutableListOf<OcrBoundingBox>() }
    val orphans = mutableListOf<OcrBoundingBox>()
    for (box in boxes) {
        val centerX = (box.left + box.right) / 2f
        val centerY = (box.top + box.bottom) / 2f
        var target = panels.indexOfFirst { it.contains(centerX, centerY) }
        if (target < 0) {
            var bestOverlap = 0f
            var bestIndex = -1
            panels.forEachIndexed { index, panel ->
                val overlap = overlapArea(panel, box)
                if (overlap > bestOverlap) { bestOverlap = overlap; bestIndex = index }
            }
            target = bestIndex
        }
        if (target >= 0) buckets[target] += box else orphans += box
    }
    return buckets.flatMap { orderBoxesWithinPanel(it, direction) } +
        orderBoxesWithinPanel(orphans, direction)
}
