1. In AutoReadEngine companion, add:
```kotlin
/**
 * Порядок реплик С УЧЁТОМ ПАНЕЛЕЙ: рамки раскладываются по панелям манги
 * (панели уже в порядке чтения), внутри панели — обычный порядок
 * [orderRegions]. Пустой список панелей = обычное поведение.
 */
internal fun orderLinesByPanels(
    lines: List<Line>,
    order: String,
    panels: List<OcrBoundingBox>,
): List<Line> {
    if (lines.size < 2 || panels.isEmpty()) return orderRegions(lines, order)
    val direction = when (order) {
        "ltr" -> ReadingDirection.LTR
        "vertical" -> ReadingDirection.VERTICAL
        else -> ReadingDirection.RTL
    }
    val groups = orderBoxesByPanels(
        boxes = lines.map { it.boundingBox },
        panels = panels,
        direction = direction,
    )
    // Возвращаем те же объекты Line в панельном порядке: orderBoxesByPanels
    // вернул те же рамки, поэтому ищем исходную строку по рамке.
    val byBox = lines.associateBy { it.boundingBox }
    return groups.mapNotNull { byBox[it] }
}
