     /**
      * Check if the image can be panned to the left
      */
     fun canPanLeft(): Boolean = canPan { it.left }

     /**
      * Check if the image can be panned to the right
      */
     fun canPanRight(): Boolean = canPan { it.right }

     /**
      * Check whether the image can be panned.
      * @param fn a function that returns the direction to check for
      */
     private fun canPan(fn: (RectF) -> Float): Boolean {
         (pageView as? SubsamplingScaleImageView)?.let { view ->
             RectF().let {
                 view.getPanRemaining(it)
                 return fn(it) > 1
             }
         }
         return false
     }

     /**
      * Pans the image to the left by a screen's width worth.
      */
     fun panLeft() {
         pan { center, view -> center.also { it.x -= view.width / view.scale } }
     }

     /**
      * Pans the image to the right by a screen's width worth.
      */
     fun panRight() {
         pan { center, view -> center.also { it.x += view.width / view.scale } }
     }

     /**
      * Pans the image.
      * @param fn a function that computes the new center of the image
      */
     private fun pan(fn: (PointF, SubsamplingScaleImageView) -> PointF) {
         (pageView as? SubsamplingScaleImageView)?.let { view ->

             val target = fn(view.center ?: return, view)
             view.animateCenter(target)!!
                 .withEasing(EASE_OUT_QUAD)
                 .withDuration(250)
                 .withInterruptible(true)
                 .start()
         }
     }

     private fun prepareNonAnimatedImageView() {
         if (pageView is SubsamplingScaleImageView) return
         removeView(pageView)

         pageView = if (isWebtoon) {
             WebtoonSubsamplingImageView(context)
         } else {
             SubsamplingScaleImageView(context)
         }.apply {
             setMaxTileSize(ImageUtil.hardwareBitmapThreshold)
             setDoubleTapZoomStyle(SubsamplingScaleImageView.ZOOM_FOCUS_CENTER)
             setPanLimit(SubsamplingScaleImageView.PAN_LIMIT_INSIDE)
             setMinimumTileDpi(180)
             setOnStateChangedListener(
                 object : SubsamplingScaleImageView.OnStateChangedListener {
                     override fun onScaleChanged(newScale: Float, origin: Int) {
                         this@ReaderPageImageView.onScaleChanged(newScale)
                         panelDebugOverlay.invalidate()
                     }

                     override fun onCenterChanged(newCenter: PointF?, origin: Int) {
                         panelDebugOverlay.invalidate()
                         invalidate()
                     }
                 },
             )
             setOnClickListener { this@ReaderPageImageView.onViewClicked() }
         }
         addView(pageView, MATCH_PARENT, MATCH_PARENT)
         bringChildToFront(panelDebugOverlay)
     }

     private fun SubsamplingScaleImageView.setupZoom(config: Config?) {
         // 5x zoom
         maxScale = scale * MAX_ZOOM_SCALE
         setDoubleTapZoomScale(scale * 2)

         when (config?.zoomStartPosition) {
             ZoomStartPosition.LEFT -> setScaleAndCenter(scale, PointF(0F, 0F))
             ZoomStartPosition.RIGHT -> setScaleAndCenter(scale, PointF(sWidth.toFloat(), 0F))
             ZoomStartPosition.CENTER -> setScaleAndCenter(scale, center)
             null -> {}
         }
     }

     private fun setNonAnimatedImage(
         data: Any,
         config: Config,
     ) = (pageView as? SubsamplingScaleImageView)?.apply {
         setDoubleTapZoomDuration(config.zoomDuration.getSystemScaledDuration())
         setMinimumScaleType(config.minimumScaleType)
         setMinimumDpi(1) // Just so that very small image will be fit for initial load
         setCropBorders(config.cropBorders)
         setOnImageEventListener(
             object : SubsamplingScaleImageView.DefaultOnImageEventListener() {
                 override fun onReady() {
                     setupZoom(config)
                     val direction = pendingOnPageReadyDirection
                     pendingOnPageReadyDirection = null
                     when {
                         direction != null -> onPageReady(direction)
                         isVisibleOnScreen() -> onPageReady(true)
                     }
                     this@ReaderPageImageView.onImageLoaded()
                 }

                 override fun onImageLoadError(e: Exception) {
                     this@ReaderPageImageView.onImageLoadError(e)
                 }
             },
         )

         when (data) {
             is BitmapDrawable -> {
                 setImage(ImageSource.bitmap(data.bitmap))
                 isVisible = true
             }
             is BufferedSource -> {
                 if (!isWebtoon || alwaysDecodeLongStripWithSSIV) {
                     setHardwareConfig(ImageUtil.canUseHardwareBitmap(data))
                     setImage(ImageSource.inputStream(data.peek().inputStream()))
                     isVisible = true
                     return@apply
                 }

                 ImageRequest.Builder(context)
                     .data(data.peek())
                     .memoryCachePolicy(CachePolicy.DISABLED)
                     .diskCachePolicy(CachePolicy.DISABLED)
                     .target(
                         onSuccess = { result ->
                             val image = result as BitmapImage
                             setImage(ImageSource.bitmap(image.bitmap))
                             isVisible = true
                         },
                     )
                     .listener(
                         onError = { _, result ->
                             onImageLoadError(result.throwable)
                         },
                     )
                     .size(ViewSizeResolver(this@ReaderPageImageView))
                     .precision(Precision.INEXACT)
                     .cropBorders(config.cropBorders)
                     .customDecoder(true)
                     .crossfade(false)
                     .build()
                     .let(context.imageLoader::enqueue)
             }
             else -> {
                 throw IllegalArgumentException("Not implemented for class ${data::class.simpleName}")
             }
         }
     }

     private fun prepareAnimatedImageView() {
         if (pageView is AppCompatImageView) return
         removeView(pageView)

         pageView = if (isWebtoon) {
             AppCompatImageView(context)
         } else {
             PhotoView(context)
         }.apply {
             adjustViewBounds = true

             if (this is PhotoView) {
                 setScaleLevels(1F, 2F, MAX_ZOOM_SCALE)
                 setOnMatrixChangeListener {
                     invalidate()
                 }
                 // Force 2 scale levels on double tap
                 setOnDoubleTapListener(
                     object : GestureDetector.SimpleOnGestureListener() {
                         override fun onDoubleTap(e: MotionEvent): Boolean {
                             if (scale > 1F) {
                                 setScale(1F, e.x, e.y, true)
                             } else {
                                 setScale(2F, e.x, e.y, true)
                             }
                             return true
                         }

                         override fun onSingleTapConfirmed(e: MotionEvent): Boolean {
                             this@ReaderPageImageView.onViewClicked()
                             return super.onSingleTapConfirmed(e)
                         }
                     },
                 )
                 setOnScaleChangeListener { _, _, _ ->
                     this@ReaderPageImageView.onScaleChanged(scale)
                 }
             }
         }
         addView(pageView, MATCH_PARENT, MATCH_PARENT)
         bringChildToFront(panelDebugOverlay)
     }

     private fun setAnimatedImage(
         data: Any,
         config: Config,
     ) = (pageView as? AppCompatImageView)?.apply {
         if (this is PhotoView) {
             setZoomTransitionDuration(config.zoomDuration.getSystemScaledDuration())
         }

         val request = ImageRequest.Builder(context)
             .data(data)
             .memoryCachePolicy(CachePolicy.DISABLED)
             .diskCachePolicy(CachePolicy.DISABLED)
             .target(
                 onSuccess = { result ->
                     val drawable = result.asDrawable(context.resources)
                     setImageDrawable(drawable)
                     (drawable as? Animatable)?.start()
                     isVisible = true
                     this@ReaderPageImageView.onImageLoaded()
                 },
             )
             .listener(
                 onError = { _, result ->
                     onImageLoadError(result.throwable)
                 },
             )
             .crossfade(false)
             .build()
         context.imageLoader.enqueue(request)
     }

     fun setCachedOcrResult(result: OcrPageResult?) {
         cachedOcrResult = result
         invalidateActiveOverlayLayout()
         invalidate()
     }

     fun clearCachedOcrResult() {
         cachedOcrResult = null
         invalidateActiveOverlayLayout()
         invalidate()
     }

     fun tryConsumeOcrTap(rawX: Float, rawY: Float): Boolean {
         val localPoint = rawPointToLocalPoint(rawX, rawY) ?: return false
         return tryConsumeOcrTapLocal(localPoint.x, localPoint.y)
     }

     fun tryConsumeActiveOcrOverlayTap(rawX: Float, rawY: Float): ReaderActiveOcrTapResult? {
         val localPoint = rawPointToLocalPoint(rawX, rawY) ?: return null
         return tryConsumeActiveOcrOverlayTapLocal(localPoint.x, localPoint.y)
     }

     fun tryConsumeOcrTapLocal(localX: Float, localY: Float): Boolean {
         val result = cachedOcrResult ?: return false
         val sourcePoint = localPointToFilePoint(localX, localY) ?: return false
         val region = result.findRegionAt(sourcePoint.x, sourcePoint.y) ?: return false

         val displayText = normalizeOcrTextForDisplay(region.text)

         onOcrRegionClicked?.invoke(
             ReaderPageOcrRegionTap(
                 regionOrder = region.order,
                 displayText = displayText,
                 queryText = flattenOcrTextForQuery(region.text),
                 boundingBox = region.boundingBox,
                 textOrientation = region.textOrientation,
                 anchorRectOnScreen = boundingBoxToScreenRect(region.boundingBox),
                 initialSelectionOffset = resolveInitialSelectionOffset(region, displayText, localX, localY),
             ),
         )
         return true
     }

     fun tryConsumeActiveOcrOverlayTapLocal(
         localX: Float,
         localY: Float,
     ): ReaderActiveOcrTapResult? {
         val overlayLayout = getOrBuildActiveOverlayLayout() ?: return null
         if (!overlayLayout.bubbleRect.contains(localX, localY)) return null
         return if (ocrOverlayRenderer.isPointNearText(overlayLayout, localX, localY)) {
             ReaderActiveOcrTapResult.SelectWord(
                 ocrOverlayRenderer.resolveQueryOffset(overlayLayout, localX, localY),
             )
         } else {
             ReaderActiveOcrTapResult.BubbleTap
         }
     }

     override fun dispatchDraw(canvas: Canvas) {
         super.dispatchDraw(canvas)
         drawOcrPageMarks(canvas)
         drawActiveOcrOverlay(canvas)
     }

     /**
      * Пометки порядка чтения из буфера скриншотов — те же разноцветные рамки с
      * номерами, что во вкладке «Скриншоты», но на самой странице.
      *
      * Рисуем здесь, а не оверлеем Compose, потому что координаты регионов
      * лежат в пикселях страницы, а не окна: страница не занимает всю область
      * (поля у манги, длинная лента вебтуна), и карта с экрана на страницу
      * теряется на полях. [SubsamplingScaleImageView.fileToViewRect] делает
      * правильную проекцию сама — вместе с зумом, панорамой, поворотом на
      * 90/180/270 и обрезкой рамок, а перерисовку при всех этих изменениях уже
      * дают слушатели состояния SSIV.
      *
      * Записи без геометрии (старый JSON, выделенная область, кадр из нескольких
      * страниц) пропускаются: по ним нарисовать можно только заведомо неверные
      * рамки. Анимированные страницы (GIF/WebP) рисуются через ImageView без
      * файловой геометрии — там пометок тоже нет.
      */
     private fun drawOcrPageMarks(canvas: Canvas) {
         if (!OcrPageMarksSettings.isEnabled()) return
         val pageView = pageView as? SubsamplingScaleImageView ?: return
         if (!pageView.isReady) return
         val marks = currentOcrPageMarks() ?: return

         val density = resources.displayMetrics.density
         val viewWidth = width.toFloat()
         val viewHeight = height.toFloat()
         val numberTextPaint = ocrMarksNumberPaint
         numberTextPaint.textSize = density * 10f

         // Записей на странице может быть много (вебтун: снимок на каждый экран
         // прокрутки), поэтому рисуем последние: они относятся к тому, что
         // читатель видит сейчас, а совсем старые только наслаивались бы.
         val visibleMarks = marks.takeLast(MAX_OCR_MARKS_ENTRIES)
         for (entryIndex in visibleMarks.indices) {
             val entry = visibleMarks[entryIndex]
             // Свежая запись — ярче: она про порядок чтения именно этого кадра.
             val baseColor = OcrPageMarksSettings.palette[
                 entryIndex % OcrPageMarksSettings.palette.size
             ]
             val entryAlpha = 0.4f + 0.6f * (entryIndex + 1f) / visibleMarks.size
             val markColor = baseColor.withAlpha(Color.alpha(baseColor) * entryAlpha)
             val boxPaint = ocrMarksBoxPaints[entryIndex % ocrMarksBoxPaints.size]
             boxPaint.color = markColor
+            // Нумерация ПО ПАНЕЛЯМ: внутри каждой панели манги счёт начинается
+            // заново с 1, как в комиксе (1, 2, 3 в первой панели, снова 1, 2, 3
+            // во второй). Регионы, у которых панель не определили (panelIndex =
+            // -1: текст в поле или в стыке), идут сплошной нумерацией — им
+            // «своя панель» не принадлежит.
+            var lastPanelIndex = Int.MIN_VALUE
+            var numberInPanel = 0
             for (regionIndex in entry.regions.indices) {
                 val region = entry.regions[regionIndex]
                 // v1.9.138: чистка пометок-шума с экрана. Регионы с пустым
                 // текстом и вырожденные полоски (нулевая высота на стыке
                 // кадров / микропятна) дают на странице «линии + кружки-номера
                 // без смысла» — рисовать их не надо.
                 if (region.text.isBlank()) continue
                 val hFrac = region.bottom - region.top
                 val wFrac = region.right - region.left
                 if (hFrac < 0.012f || wFrac < 0.02f) continue
                 val fileBox = entry.regionFileBoundingBox(region) ?: continue
                 val fileRect = RectF(
                     fileBox.left * entry.sourceWidth,
                     fileBox.top * entry.sourceHeight,
                     fileBox.right * entry.sourceWidth,
                     fileBox.bottom * entry.sourceHeight,
                 )
                 val viewRect = pageView.fileToViewRect(fileRect, fileCropRect) ?: continue
                 if (viewRect.width() <= 0f || viewRect.height() <= 0f) continue
                 // Экономия отрисовки длинной ленты вебтуна и обрезка всего,
                 // что уже уехало за край экрана.
                 if (!viewRect.intersect(0f, 0f, viewWidth, viewHeight)) continue

+                // Новая панель (или первый безымянный регион) — счёт с 1.
+                if (region.panelIndex != lastPanelIndex) {
+                    lastPanelIndex = region.panelIndex
+                    numberInPanel = 0
+                }
+                numberInPanel++
+
                 canvas.drawRect(viewRect, boxPaint)
-                drawOcrMarkNumber(canvas, viewRect, regionIndex + 1, markColor)
+                drawOcrMarkNumber(canvas, viewRect, numberInPanel, markColor)
             }
         }
     }

     /** Кружок с номером порядка чтения в левом верхнем углу рамки региона. */
     private fun drawOcrMarkNumber(
         canvas: Canvas,
         regionRect: RectF,
         order: Int,
         color: Int,
     ) {
         val density = resources.displayMetrics.density
         val radius = density * 9f
         val centerX = regionRect.left + radius
         val centerY = regionRect.top + radius
         val label = order.toString()
         val textPaint = ocrMarksNumberPaint
         val labelBackgroundPaint = ocrMarksNumberBackgroundPaint
         labelBackgroundPaint.color = color
         canvas.drawCircle(centerX, centerY, radius, labelBackgroundPaint)
         canvas.drawText(
             label,
             centerX - textPaint.measureText(label) / 2f,
             centerY - (textPaint.ascent() + textPaint.descent()) / 2f,
             textPaint,
         )
     }

     /**
      * Записи буфера, относящиеся к ЭТОЙ странице.
      *
      * Страница известна по [ocrPageIdentity] — тому же хуку, по которому
      * работает оверлей активной реплики, поэтому в пагере и в вебтуне (где
      * страниц в ленте много одновременно) пометки ложатся именно на ту
      * страницу, к которой относятся. Кэш по [OcrScreenshotBuffer.version]:
      * перерисовка идёт на каждом кадре анимации, фильтровать буфер заново
      * там незачем.
      */
     private fun currentOcrPageMarks(): List<OcrScreenshotEntry>? {
         val identity = ocrPageIdentity ?: return null
         val version = OcrScreenshotBuffer.version
         val cache = ocrPageMarksCache
         if (cache != null && cache.identity == identity && cache.version == version) {
             return cache.entries
         }
         val entries = OcrScreenshotBuffer.forPage(identity.chapterId, identity.pageIndex)
             .filter { it.hasSourceGeometry }
         ocrPageMarksCache = OcrPageMarksCache(identity, version, entries)
         return entries
     }

     private fun drawActiveOcrOverlay(canvas: Canvas) {
         // Выключатель из Настройки → Распознавание: пользователь убирает
         // оверлей совсем, когда текст поверх страницы мешает читать картинку.
         if (!ocrPrefs.ocrPageTextOverlay().get()) return
         val overlayLayout = getOrBuildActiveOverlayLayout() ?: return
         // Подложка под текстом обязательна. Раньше её убрали («solid white
         // background box»), и на светлой странице белый текст поверх белой
         // бумаги просто исчезал — оверлей был, а прочитать его нельзя.
         // Заливка идёт по textRect (области текста), а не по всему
         // boundingBox, и полупрозрачная: картинка под ней остаётся видна.
         val pad = resources.displayMetrics.density * 4f
         val bg = RectF(overlayLayout.textRect).apply { inset(-pad, -pad) }
         val radius = resources.displayMetrics.density * 6f
         canvas.drawRoundRect(bg, radius, radius, ocrOverlayBackgroundPaint)
         canvas.drawRoundRect(bg, radius, radius, ocrOverlayStrokePaint)
         ocrOverlayRenderer.drawOverlay(canvas, overlayLayout)
     }

     private fun resolveInitialSelectionOffset(
         region: mihon.domain.ocr.model.OcrRegion,
         normalizedDisplayText: String,
         localX: Float,
         localY: Float,
     ): Int {
         val overlayLayout = ocrOverlayRenderer.buildLayout(
             bubbleRect = boundingBoxToLocalRect(region.boundingBox) ?: return 0,
             displayText = normalizedDisplayText,
             textOrientation = region.textOrientation,
             highlightRange = null,
         ) ?: return 0
         return if (ocrOverlayRenderer.isPointNearText(overlayLayout, localX, localY)) {
             ocrOverlayRenderer.resolveQueryOffset(overlayLayout, localX, localY)
         } else {
             0
         }
     }

     private fun getOrBuildActiveOverlayLayout(): ReaderOcrOverlayLayout? {
         activeOverlayLayout?.let { return it }

         val overlay = activeOcrOverlay ?: return null
         // Результат OCR страницы нужен как проверка, что оверлей вообще к чему
         // привязан: без распознанной страницы показывать нечего.
         cachedOcrResult ?: return null
         val bubbleRect = boundingBoxToLocalRect(overlay.boundingBox) ?: return null
         return ocrOverlayRenderer.buildLayout(
             bubbleRect = bubbleRect,
             displayText = overlay.displayText,
             textOrientation = overlay.textOrientation,
             highlightRange = overlay.highlightRange,
         )?.also {
             activeOverlayLayout = it
         }
     }

     private fun boundingBoxToLocalRect(
         boundingBox: OcrBoundingBox,
     ): RectF? {
         val localRect = boundingBoxToDisplayedRect(boundingBox) ?: return null
         return RectF(
             localRect.left.coerceIn(0f, width.toFloat()),
             localRect.top.coerceIn(0f, height.toFloat()),
             localRect.right.coerceIn(0f, width.toFloat()),
             localRect.bottom.coerceIn(0f, height.toFloat()),
         ).takeIf { it.width() > 0f && it.height() > 0f }
     }

     private fun invalidateActiveOverlayLayout() {
         activeOverlayLayout = null
     }

     private fun rawPointToLocalPoint(rawX: Float, rawY: Float): PointF? {
         val location = IntArray(2)
         getLocationOnScreen(location)
         return PointF(rawX - location[0], rawY - location[1])
     }

     private fun screenRectToLocalRect(screenRect: RectF): RectF? {
         val topLeftLocal = rawPointToLocalPoint(screenRect.left, screenRect.top) ?: return null
         val bottomRightLocal = rawPointToLocalPoint(screenRect.right, screenRect.bottom) ?: return null
         return RectF(
             min(topLeftLocal.x, bottomRightLocal.x),
             min(topLeftLocal.y, bottomRightLocal.y),
             max(topLeftLocal.x, bottomRightLocal.x),
             max(topLeftLocal.y, bottomRightLocal.y),
         )
     }

     /**
      * Прямоугольник реально отображаемой картинки внутри вьюхи, в пикселях.
      *
      * Нужен подсветке реплик: страница почти никогда не занимает всю область
      * (поля сверху/снизу у манги, по бокам у вебтуна), поэтому нормализованные
      * координаты OCR нельзя умножать на размер контейнера — рамки уезжают.
      */
     fun displayedImageRectOrNull(): RectF? = displayedImageLocalRect()

     /**
      * Размер ИСХОДНОГО изображения страницы (того же, в координатах которого
      * работает [sourceRectForScreenRect]) — в пикселях файла.
      *
      * Нужен записи скриншота: без него нормализованные координаты распознанных
      * регионов нечем перевести в пиксели страницы, и вернуть пометки на книгу
      * невозможно. null — картинка ещё не готова.
      */
     fun sourceSizeOrNull(): Pair<Int, Int>? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView ->
                 if (currentPageView.isReady && currentPageView.sWidth > 0 && currentPageView.sHeight > 0) {
                     currentPageView.sWidth to currentPageView.sHeight
                 } else {
                     null
                 }
             is ImageView -> currentPageView.drawable?.let {
                 it.intrinsicWidth to it.intrinsicHeight
             }?.takeIf { (it.first > 0 && it.second > 0) }
             else -> null
         }
     }

     private fun displayedImageLocalRect(): RectF? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView -> {
                 if (!currentPageView.isReady) return null
                 val topLeft = currentPageView.sourceToViewCoord(0f, 0f) ?: return null
                 val bottomRight = currentPageView.sourceToViewCoord(
                     currentPageView.sWidth.toFloat(),
                     currentPageView.sHeight.toFloat(),
                 ) ?: return null
                 RectF(
                     min(topLeft.x, bottomRight.x),
                     min(topLeft.y, bottomRight.y),
                     max(topLeft.x, bottomRight.x),
                     max(topLeft.y, bottomRight.y),
                 )
             }
             is ImageView -> {
                 val drawable = currentPageView.drawable ?: return null
                 RectF(0f, 0f, drawable.intrinsicWidth.toFloat(), drawable.intrinsicHeight.toFloat()).also(
                     currentPageView.imageMatrix::mapRect,
                 )
             }
             else -> null
         }
     }

     private fun localPointToSourcePoint(localX: Float, localY: Float): PointF? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView -> {
                 if (!currentPageView.isReady) return null
                 currentPageView.viewToSourceCoord(localX, localY)
             }
             is ImageView -> {
                 val drawable = currentPageView.drawable ?: return null
                 val inverse = Matrix()
                 if (!currentPageView.imageMatrix.invert(inverse)) return null

                 val points = floatArrayOf(localX, localY)
                 inverse.mapPoints(points)
                 val sourceX = points[0]
                 val sourceY = points[1]
                 if (sourceX < 0f || sourceY < 0f ||
                     sourceX > drawable.intrinsicWidth.toFloat() ||
                     sourceY > drawable.intrinsicHeight.toFloat()
                 ) {
                     null
                 } else {
                     PointF(sourceX, sourceY)
                 }
             }
             else -> null
         }
     }

     private fun localPointToFilePoint(localX: Float, localY: Float): PointF? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView -> currentPageView.viewToFilePoint(localX, localY, fileCropRect)
             else -> localPointToSourcePoint(localX, localY)
         }
     }

     private fun boundingBoxToScreenRect(
         boundingBox: OcrBoundingBox,
     ): RectF? {
         val localRect = boundingBoxToDisplayedRect(boundingBox) ?: return null
         val location = IntArray(2)
         getLocationOnScreen(location)
         return RectF(localRect).apply { offset(location[0].toFloat(), location[1].toFloat()) }
     }

     private fun boundingBoxToDisplayedRect(
         boundingBox: OcrBoundingBox,
     ): RectF? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView -> {
                 // Координаты региона нормализованы, поэтому переносим их сразу
                 // в пиксели ИСХОДНОГО изображения страницы, а не в пиксели
                 // битмапа, который видел OCR: он уменьшен и обрезан по видимой
                 // области, и от его размера зависел бы весь результат. Обрезка
                 // рамок (crop-borders) сдвигает картинку внутри файла — этот
                 // сдвиг добавляем здесь, дальше fileToViewRect развернёт его
                 // обратно вместе с поворотом и зумом.
                 val cropLeft = fileCropRect?.left ?: 0
                 val cropTop = fileCropRect?.top ?: 0
                 val sourceRect = RectF(
                     boundingBox.left * currentPageView.sWidth + cropLeft,
                     boundingBox.top * currentPageView.sHeight + cropTop,
                     boundingBox.right * currentPageView.sWidth + cropLeft,
                     boundingBox.bottom * currentPageView.sHeight + cropTop,
                 )
                 currentPageView.fileToViewRect(sourceRect, fileCropRect)
             }
             is ImageView -> {
                 val drawable = currentPageView.drawable ?: return null
                 val sourceRect = boundingBox.toSourceRect(
                     imageWidth = drawable.intrinsicWidth,
                     imageHeight = drawable.intrinsicHeight,
                 )
                 RectF(sourceRect).also(currentPageView.imageMatrix::mapRect)
             }
             else -> null
         }
     }

     private fun Int.getSystemScaledDuration(): Int {
         return (this * context.animatorDurationScale).toInt().coerceAtLeast(1)
     }

     /**
      * All of the config except [zoomDuration] will only be used for non-animated image.
      */
     data class Config(
         val zoomDuration: Int,
         val minimumScaleType: Int = SCALE_TYPE_CENTER_INSIDE,
         val cropBorders: Boolean = false,
         val zoomStartPosition: ZoomStartPosition = ZoomStartPosition.CENTER,
         val landscapeZoom: Boolean = false,
     )

     enum class ZoomStartPosition {
         LEFT,
         CENTER,
         RIGHT,
     }
 }

 private const val MAX_ZOOM_SCALE = 5F
 private const val SKIP_ZOOM_OVERLAP_THRESHOLD = 0.85F
 private const val LOADED_READER_PAGE_INDEX = -1

 /**
  * Сколько последних снимков страницы рисуется поверх неё одновременно.
  *
  * Длинный вебтун даёт по снимку на каждый экран прокрутки, и без ограничения
  * на длинной полосе оказываются десятки рамок с номерами — читать под ними
  * текст невозможно.
  */
 private const val MAX_OCR_MARKS_ENTRIES = 6

 /** Кэш пометок страницы: инвалидируется сменой страницы или версии буфера. */
 private data class OcrPageMarksCache(
     val identity: ReaderOcrPageIdentity,
     val version: Int,
     val entries: List<OcrScreenshotEntry>,
 )

 private fun OcrBoundingBox.toSourceRect(
     imageWidth: Int,
     imageHeight: Int,
 ): RectF {
     return RectF(
         left * imageWidth,
         top * imageHeight,
         right * imageWidth,
         bottom * imageHeight,
     )
 }

 private fun SubsamplingScaleImageView.viewToFilePoint(
     localX: Float,
     localY: Float,
     cropRect: Rect?,
 ): PointF? {
     if (!isReady) return null
     val sourcePoint = viewToSourceCoord(localX, localY) ?: return null
     return sourcePointToFilePoint(sourcePoint.x, sourcePoint.y, cropRect)
 }

 private fun SubsamplingScaleImageView.viewToFileRect(localRect: RectF, cropRect: Rect?): RectF? {
     val topLeft = viewToFilePoint(localRect.left, localRect.top, cropRect) ?: return null
     val bottomRight = viewToFilePoint(localRect.right, localRect.bottom, cropRect) ?: return null
     return RectF(
         minOf(topLeft.x, bottomRight.x),
         minOf(topLeft.y, bottomRight.y),
         maxOf(topLeft.x, bottomRight.x),
         maxOf(topLeft.y, bottomRight.y),
     )
 }

 private fun SubsamplingScaleImageView.fileToViewRect(fileRect: RectF, cropRect: Rect?): RectF? {
     val topLeft = fileToViewPoint(fileRect.left, fileRect.top, cropRect) ?: return null
     val bottomRight = fileToViewPoint(fileRect.right, fileRect.bottom, cropRect) ?: return null
     return RectF(
         minOf(topLeft.x, bottomRight.x),
         minOf(topLeft.y, bottomRight.y),
         maxOf(topLeft.x, bottomRight.x),
         maxOf(topLeft.y, bottomRight.y),
     )
 }

 private fun SubsamplingScaleImageView.fileToViewPoint(
     fileX: Float,
     fileY: Float,
     cropRect: Rect?,
 ): PointF? {
     if (!isReady) return null
     val sourcePoint = filePointToSourcePoint(fileX, fileY, cropRect) ?: return null
     return sourceToViewCoord(sourcePoint.x, sourcePoint.y)
 }

 private fun SubsamplingScaleImageView.sourcePointToFilePoint(
     sourceX: Float,
     sourceY: Float,
     cropRegion: Rect?,
 ): PointF {
     val filePoint = when (imageRotation) {
         com.davemorrissey.labs.subscaleview.ImageRotation.ROTATION_90 -> {
             PointF(sourceY, sHeight - sourceX)
         }
         com.davemorrissey.labs.subscaleview.ImageRotation.ROTATION_180 -> {
             PointF(sWidth - sourceX, sHeight - sourceY)
         }
         com.davemorrissey.labs.subscaleview.ImageRotation.ROTATION_270 -> {
             PointF(sWidth - sourceY, sourceX)
         }
         else -> PointF(sourceX, sourceY)
     }
     if (cropRegion != null) {
         filePoint.offset(cropRegion.left.toFloat(), cropRegion.top.toFloat())
     }
     return filePoint
 }

 private fun SubsamplingScaleImageView.filePointToSourcePoint(
     fileX: Float,
     fileY: Float,
     cropRegion: Rect?,
 ): PointF? {
     val croppedX = fileX - (cropRegion?.left ?: 0)
     val croppedY = fileY - (cropRegion?.top ?: 0)
     val sourcePoint = when (imageRotation) {
         com.davemorrissey.labs.subscaleview.ImageRotation.ROTATION_90 -> {
             PointF(sHeight - croppedY, croppedX)
         }
         com.davemorrissey.labs.subscaleview.ImageRotation.ROTATION_180 -> {
             PointF(sWidth - croppedX, sHeight - croppedY)
         }
         com.davemorrissey.labs.subscaleview.ImageRotation.ROTATION_270 -> {
             PointF(croppedY, sWidth - croppedX)
         }
         else -> PointF(croppedX, croppedY)
     }
     return sourcePoint.takeIf {
         it.x in 0f..sWidth.toFloat() &&
             it.y in 0f..sHeight.toFloat()
     }
 }

 private fun RectF.toRect(): Rect? {
     return Rect(
         left.toInt(),
         top.toInt(),
         right.toInt(),
         bottom.toInt(),
     ).takeIf { it.width() > 0 && it.height() > 0 }
 }

 /** Тот же цвет с другой прозрачностью: рамки пометок должны быть полупрозрачными. */
 private fun Int.withAlpha(alpha: Float): Int = Color.argb(
     alpha.toInt().coerceIn(0, 255),
     Color.red(this),
     Color.green(this),
     Color.blue(this),
 )

 private class PanelDebugOverlayView(
     context: Context,
 ) : View(context) {

     private var detections: List<DebugPanelDetection> = emptyList()
     private var bubbles: List<DebugPanelDetection> = emptyList()
     private var pageView: SubsamplingScaleImageView? = null
     private var cropRect: Rect? = null

     private val panelBoxPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
         color = Color.argb(220, 0, 255, 120)
         style = Paint.Style.STROKE
         strokeWidth = context.resources.displayMetrics.density * 2f
     }
     private val bubbleBoxPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
         color = Color.argb(220, 255, 60, 60)
         style = Paint.Style.STROKE
         strokeWidth = context.resources.displayMetrics.density * 2f
     }
     private val labelPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
         color = Color.WHITE
         textSize = context.resources.displayMetrics.density * 12f
     }
     private val labelBackgroundPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
         color = Color.argb(190, 0, 0, 0)
         style = Paint.Style.FILL
     }
     private val textBounds = RectF()

     fun setDetections(
         detections: List<DebugPanelDetection>,
         bubbles: List<DebugPanelDetection>,
         pageView: SubsamplingScaleImageView?,
         cropRect: Rect?,
     ) {
         this.detections = detections
         this.bubbles = bubbles
         this.pageView = pageView
         this.cropRect = cropRect?.let(::Rect)
         isVisible = (detections.isNotEmpty() || bubbles.isNotEmpty()) && pageView != null
         invalidate()
     }

     override fun onDraw(canvas: Canvas) {
         super.onDraw(canvas)

         val pageView = pageView ?: return
         if (!isVisible || !pageView.isReady) return

         drawDetections(canvas, pageView, detections, panelBoxPaint, "P")
         drawDetections(canvas, pageView, bubbles, bubbleBoxPaint, "B")
     }

     private fun drawDetections(
         canvas: Canvas,
         pageView: SubsamplingScaleImageView,
         items: List<DebugPanelDetection>,
         boxPaint: Paint,
         prefix: String,
     ) {
         items.forEachIndexed { index, detection ->
             val fileRect = RectF(detection.rect)
             val viewRect = pageView.fileToViewRect(fileRect, cropRect) ?: return@forEachIndexed
             val left = viewRect.left
             val top = viewRect.top
             val right = viewRect.right
             val bottom = viewRect.bottom

             canvas.drawRect(left, top, right, bottom, boxPaint)

             val label = "$prefix${index + 1} ${(detection.confidence * 100).roundToInt()}%"
             val textWidth = labelPaint.measureText(label)
             val textHeight = labelPaint.fontMetrics.let { it.descent - it.ascent }
             val padding = context.resources.displayMetrics.density * 4f
             textBounds.set(
                 left,
                 (top - textHeight - padding * 2).coerceAtLeast(0f),
                 left + textWidth + padding * 2,
                 top,
             )
             canvas.drawRect(textBounds, labelBackgroundPaint)
             canvas.drawText(
                 label,
                 textBounds.left + padding,
                 textBounds.bottom - padding - labelPaint.fontMetrics.descent,
                 labelPaint,
             )
         }
     }
 }

