                 var speakIndex = 0

                 // «Сканировать и озвучивать страницу целиком»: один снимок и одна
                 // озвучка всей страницы вместо реплики за репликой. Переключатель
                 // существовал, но `ReaderViewModel.autoScanAndSpeak` не вызывался
