                 // озвучить страницу»: у онлайн-движков так один сетевой кадр
                 // превращается в одну реплику без меж-баллонных пауз.
                 val wholePageMode = (autoReadMode == "page" || prefs.autoScanAndSpeak().get()) && speakable.size > 1
                 if (wholePageMode) {
