val screenshotJpeg: ByteArray? = if (prefs.autoScreenshotEnabled().get() && !ocrBitmap.isRecycled) {
    runCatching { encodeJpeg(ocrBitmap, JPEG_QUALITY) }.getOrNull()
} else null

