         // мусор; до v1.9.140 такие строки отбрасывались (нет 3-букв. слова).
         private val STRONG_SHORT_RE = Regex("^[\\p{L}]{1,2}[!?…~]{1,4}$")
         private val CYRILLIC_WORD_RE = Regex("[\\u0400-\\u04FF]{3,}")
         private val LATIN_WORD_RE = Regex("[A-Za-z]{3,}")
