                                             contentDescription = "Скрыть или показать кнопки конструктора",
                                         )
                                     }
                                 }
                                 if (ctorExpanded) {
                                     userActs.filterNot { it.title.startsWith("Пресет") }.forEach { act ->
                                         Row(
                                             modifier = Modifier.fillMaxWidth(),
