         NEUTRAL(1f, 1f, ""),
         /** Страх: голос выше и быстрее, «сдавленно». */
         FEAR(1.3f, 1.4f, "!!"),
         /** Утешение: ниже и медленнее, «объятие». */
         COMFORT(0.85f, 0.82f, "☺"),
         ANGER(0.9f, 1.18f, "><"),
         SADNESS(0.88f, 0.78f, "…"),
         JOY(1.14f, 1.12f, "^_^"),
