package eu.kanade.tachiyomi.data.tts

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

/**
 * Закрепление голоса персонажа за книгой.
 *
 * Голос персонажа выбирается по номеру слота, а сам слот хранится в
 * настройках. Поэтому важно одно: закреплённый слот не должен отменяться,
 * а новый персонаж обязан получить свободный.
 */
class BookVoiceSlotTest {

    /** Зеркалит решение движка в voiceSlotFor. */
    private fun slotFor(remembered: Int, nextFree: Int): Int =
        if (remembered > 0 && nextFree > remembered) remembered else nextFree

    @Test
    fun `закреплённый голос персонажа сохраняется`() {
        // Персонаж занимал слот 1, следующий свободный — 3. Голос не должен
        // прыгать: иначе после перезапуска герой заговорит иначе.
        assertEquals(1, slotFor(remembered = 1, nextFree = 3))
    }

    @Test
    fun `новый персонаж получает свободный слот`() {
        assertEquals(2, slotFor(remembered = 0, nextFree = 2))
    }

    @Test
    fun `если закреплённый слот уже занят другим — берём свободный`() {
        // Слот 1 в этой сцене занял другой герой: отдаём 3, чтобы не было двух
        // персонажей с одним голосом.
        assertEquals(3, slotFor(remembered = 1, nextFree = 1))
        assertEquals(3, slotFor(remembered = 1, nextFree = 2))
    }

    @Test
    fun `закреплённый слот стабилен между запусками`() {
        // Два чтения подряд: в первом слот назначили, во втором он уже известен.
        val nextFreeFirst = 1
        val assigned = slotFor(remembered = 0, nextFree = nextFreeFirst)
        val nextFreeSecond = nextFreeFirst // персонаж только один в сцене
        assertEquals(assigned, slotFor(remembered = assigned, nextFree = nextFreeSecond))
        assertTrue(assigned > 0)
    }
}

