         // инициализацию класса. Набор символов тот же, дефис теперь тире.
         private val CHROME_CHARS_RE =
             Regex("[→←⇐⇒↔—–\\-|/\\\\\\d\\s,.\\(\\)«»\\[\\]\\\"']")
