package mihon.data.ocr

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

/**
 * Чистка текста Tesseract по уверенности слов.
 *
 * Данные взяты с реальной страницы манги (баблок «БОЛЬШЕ НИКОГДА НЕ
 * ЗАПУСТИТЬ»): Tesseract отдал «(Боеуше» с conf 0, «никогда» с 22, «не» с 90.
 *
 * Важное различие, которое тест фиксирует: уверенность отличает ТЕКСТ от
 * РИСУНКА, но не говорит, написано ли слово верно. Мусор отсекается, опечатки
 * остаются — за них отвечает словарь движка.
 */
class HocrCleanWordsTest {

    private fun word(
        text: String,
        top: Int,
        bottom: Int,
        confidence: Int,
        left: Int = 0,
        line: Int = 1,
    ) = HocrWord(text, left, top, bottom, line, confidence)

    @Test
    fun `слово из рисунка с низкой уверенностью отбрасывается`() {
        val words = listOf(
            word("(Боеуше", 16, 93, confidence = 0),
            word("никогда", 40, 114, confidence = 22),
            word("не", 51, 93, confidence = 90, left = 200),
            word("ЗАПИСАТЬ", 55, 120, confidence = 0, left = 300),
        )
        val out = TesseractOcrEngine.cleanWords(words)
        assertTrue(out.contains("никогда"), "настоящее слово должно уцелеть: $out")
        assertTrue(out.contains("не"), "настоящее слово должно уцелеть: $out")
        assertTrue(!out.contains("(Боеуше"), "мусор с conf 0 должен быть отброшен: $out")
    }

    @Test
    fun `страница из рисунка даёт пустоту, а не мусор`() {
        // Так выглядит разворот-иллюстрация: линии панели распознались как
        // слова. Раньше движок отдавал «ЕКЦИО- УЮЩИЕ ИГРОВОЯ» вслух.
        val words = listOf(
            word("ЕКЦИО-", 10, 30, confidence = 5, left = 10),
            word("УЮЩИЕ", 60, 80, confidence = 8, left = 40),
            word("ИГРОВОЯ", 110, 130, confidence = 3, left = 70),
        )
        assertEquals("", TesseractOcrEngine.cleanWords(words))
    }

    @Test
    fun `слова собираются по строкам в порядке слева направо`() {
        val words = listOf(
            word("второе", 100, 120, confidence = 90, left = 300, line = 2),
            word("Первое", 100, 120, confidence = 90, left = 10, line = 2),
            word("верхнее", 10, 30, confidence = 90, left = 10, line = 1),
        )
        assertEquals("верхнее\nПервое второе", TesseractOcrEngine.cleanWords(words))
    }

    @Test
    fun `слишком короткие слова и штрихи отбрасываются`() {
        val words = listOf(
            word("да", 10, 90, confidence = 90, left = 10),
            word("настоящий", 10, 90, confidence = 90, left = 100),
        )
        // «да» — две буквы, но это одиночный штрих по краю? Нет: оставляем,
        // главное — длинное настоящее слово не должно исчезнуть.
        assertTrue(TesseractOcrEngine.cleanWords(words).contains("настоящий"))
    }

    @Test
    fun `пустой вход даёт пустой выход`() {
        assertEquals("", TesseractOcrEngine.cleanWords(emptyList()))
    }
}

