private const val BORDER_FILLED_RATIO_LIMIT = 0.0025f
private const val BORDER_THRESHOLD_FOR_BLACK = (255f * 0.75f).toInt()
private const val BORDER_THRESHOLD_FOR_WHITE = (255f - (255f * 0.75f)).toInt()

