 @Composable
 fun OcrBubbleSettingsDialog(
     onDismissRequest: () -> Unit,
     onOpenFullSettings: () -> Unit,
     /** Проброс выбранного порядка в состояние читалки (цикл-кнопка плавающего меню). */
