package eu.kanade.presentation.reader.components

import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.BoxWithConstraints
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.offset
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.width
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.unit.IntOffset
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import eu.kanade.tachiyomi.data.tts.AutoReadEngine
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import kotlin.math.roundToInt

/**
 * «Линейка чтения»: подсветка текущей озвучиваемой реплики.
 *
 * Вид настраивается (Настройки → Озвучка):
 * - [OcrPreferences.highlightColor] — цвет пятна/рамки/линии;
 * - [OcrPreferences.highlightStyle] — `bubble` (мягкие еле заметные кружки,
 *   по умолчанию), `box` (рамка), `underline` (подчёркивание) или `both`;
 * - [OcrPreferences.highlightWidth] — толщина в dp для box/underline.
 *
 * В режиме `bubble` никакие прямоугольники не рисуются вообще: текущая
 * реплика — радиальное пятно-круг, сходящее к нулю на краях, а история и
 * план чтения — совсем тусклые кружки. Промах бокса при таком пятне не
 * режет глаз, в отличие от жёсткой рамки.
 *
 * Номер реплики показывается рядом с рамкой: он нужен глазами, чтобы видеть
 * порядок чтения, но в озвучку не попадает (снимается SpeechMarkup.strip).
 *
 * Компонент молчал с v1.9.44: три настройки подсветки и переключатель «показывать
 * номера реплик» ничего не делали, потому что здесь ничего не рисовалось.
 */
@Composable
fun AutoReadHighlight(
    region: AutoReadEngine.SpokenRegion,
    modifier: Modifier = Modifier,
    engine: AutoReadEngine? = null,
    /** The actual displayed image rect within the parent (0..1 normalized).
     *  When null, falls back to the full composable area (may be wrong
     *  with letterboxed images). Set this from ReaderPageImageView.displayedImageLocalRect(). */
    imageRect: android.graphics.RectF? = null,
) {
    val prefs = remember { Injekt.get<OcrPreferences>() }
    // Не кэшируем навсегда: пользователь меняет цвет в настройках — рамки
    // перекрашиваются со следующей реплики, без перезапуска читалки
    val accent = Color(prefs.highlightColor().get().toULong().toLong())
    val style = prefs.highlightStyle().get()
    val strokeWidth = prefs.highlightWidth().get().coerceIn(1f, 12f)
    val showNumbers = prefs.showSpeechNumbers().get()

    // Рамка приходит в координатах СТРАНИЦЫ (0..1): авточтение возвращает
    // координаты кадра на страницу через pageBox. Без прямоугольника страницы
    // (поля сверху/снизу у манги, по бокам у вебтуна) считаем от всего окна.
    val box = region.box
    val drawn = engine?.frameRegions?.collectAsState()?.value.orEmpty()

    BoxWithConstraints(modifier = modifier.fillMaxSize()) {
        val maxW = maxWidth
        val maxH = maxHeight
        val density = LocalDensity.current

        // Пиксели считаем сами: Modifier.offset(x, y) ждёт Dp, а рамка приходит
        // в долях страницы, и лишний перевод в dp путал бы масштаб.
        fun place(left: Float, top: Float, right: Float, bottom: Float): IntArray {
            val z = imageRect
            val zl = z?.left ?: 0f
            val zt = z?.top ?: 0f
            val zw = (z?.right ?: 1f) - zl
            val zh = (z?.bottom ?: 1f) - zt
            val x = zl + left * zw
            val y = zt + top * zh
            val w = ((right - left) * zw).coerceAtLeast(0.004f)
            val h = ((bottom - top) * zh).coerceAtLeast(0.004f)
            return intArrayOf(
                (x * maxW.value).roundToInt(),
                (y * maxH.value).roundToInt(),
                (w * maxW.value).roundToInt(),
                (h * maxH.value).roundToInt(),
            )
        }

        // План чтения и уже озвученные реплики — тусклыми кружками, чтобы видеть
        // «где я» и «что дальше», не перекрывая рисунок.
        drawn.forEach { frame ->
            // v1.9.135: вырожденные рамки (пустой текст, почти нулевая высота
            // на стыке кадров) отрисовывались артефактом «тонкая линия через
            // страницу + бейдж». Такие регионы не рисуем вовсе.
            if (frame.text.isBlank() ||
                frame.box.bottom - frame.box.top < 0.012f ||
                frame.box.right - frame.box.left < 0.02f
            ) return@forEach
            when (frame.state) {
                AutoReadEngine.FrameRegion.State.DONE,
                AutoReadEngine.FrameRegion.State.UPCOMING,
                -> {
                    val p = place(frame.box.left, frame.box.top, frame.box.right, frame.box.bottom)
                    Box(
                        modifier = Modifier
                            .offset { IntOffset(p[0], p[1]) }
                            .width(p[2].dp)
                            .height(p[3].dp)
                            .background(
                                brush = Brush.radialGradient(
                                    colors = listOf(
                                        accent.copy(alpha = if (frame.state == AutoReadEngine.FrameRegion.State.DONE) 0.04f else 0.02f),
                                        Color.Transparent,
                                    ),
                                ),
                                shape = RoundedCornerShape(percent = 50),
                            ),
                    )
                }

                AutoReadEngine.FrameRegion.State.CURRENT -> Unit
            }
        }

        val cur = place(box.left, box.top, box.right, box.bottom)
        val stroke = strokeWidth.dp
        val label = if (showNumbers) region.index.toString() else region.marks.trim()

        // v1.9.137: «баг с эллипсом». Текущая реплика порой приходила рамкой
        // во весь кадр (целый видимый регион скана): в стиле box/both она
        // рисовалась огранённым 50%-скруглением — ВЕРТИКАЛЬНЫЙ эллипс через
        // пол-экрана поверх арта, где текста нет. Такие гигантские рамки
        // бессмысленны — не рисуем ни контур, ни бейдж.
        val boxTall = box.bottom - box.top
        val boxWide = box.right - box.left
        if (boxTall > 0.6f || boxWide > 0.9f) return@BoxWithConstraints

        when (style) {
            // Мягкое пятно: прямоугольных рамок нет вовсе, только радиальный
            // круг по центру реплики.
            "bubble" -> Box(
                modifier = Modifier
                    .offset { IntOffset(cur[0], cur[1]) }
                    .width(cur[2].dp)
                    .height(cur[3].dp)
                    .background(
                        brush = Brush.radialGradient(
                            colors = listOf(accent.copy(alpha = 0.22f), Color.Transparent),
                        ),
                        shape = RoundedCornerShape(percent = 50),
                    ),
            )

            "underline" -> Box(
                modifier = Modifier
                    .offset { IntOffset(cur[0], cur[1] + cur[3]) }
                    .width(cur[2].dp)
                    .height(stroke),
            ) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(accent.copy(alpha = 0.55f), CircleShape),
                )
            }

            // "box" и "both" — рамка вокруг реплики; "both" добавляет пятно.
            else -> Box(
                modifier = Modifier
                    .offset { IntOffset(cur[0], cur[1]) }
                    .width(cur[2].dp)
                    .height(cur[3].dp)
                    .then(
                        if (style == "both") {
                            Modifier.background(
                                brush = Brush.radialGradient(
                                    colors = listOf(accent.copy(alpha = 0.14f), Color.Transparent),
                                ),
                                shape = RoundedCornerShape(percent = 50),
                            )
                        } else {
                            Modifier
                        },
                    )
                    // v1.9.137: прямоугольник со слегка скруглёнными углами
                    // (раньше RoundedCornerShape(percent = 50) = ЭЛЛИПС на
                    // длинных рамках — он же на скриншоте как «эллипс через
                    // весь экран там, где текста нет»).
                    .border(stroke, accent.copy(alpha = 0.65f), RoundedCornerShape(10.dp)),
            )
        }

        // Номер реплики — служебная метка, в озвучку не идёт, но читателю
        // показывает порядок чтения.
        if (showNumbers && label.isNotBlank()) {
            // Бейдж СЛЕВА-НАД рамкой: раньше он ложился ровно на левый край
            // рамки и перекрывал первую букву текста («2ЛЕНА СЕВЕС…», «2Мир»).
            // Выносим за границу рамки и не даём уйти за экран (кламп к 0).
            val bx = (cur[0] - 26.dp.value).roundToInt().coerceAtLeast(0)
            val by = (cur[1] - 22.dp.value).roundToInt().coerceAtLeast(0)
            val numberOffset = IntOffset(bx, by)
            Box(
                modifier = Modifier
                    .offset { numberOffset }
                    .background(accent.copy(alpha = 0.85f), CircleShape)
                    .padding(horizontal = 6.dp, vertical = 1.dp),
            ) {
                Text(
                    text = label,
                    color = Color.Black,
                    fontSize = 11.sp,
                )
            }
        }
    }
}

package eu.kanade.presentation.reader.components

import androidx.compose.foundation.BorderStroke
import androidx.compose.foundation.gestures.detectDragGestures
import androidx.compose.foundation.gestures.detectTapGestures
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.BoxWithConstraints
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.offset
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.size
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.outlined.RecordVoiceOver
import androidx.compose.material3.Icon
import androidx.compose.material3.Surface
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.input.pointer.pointerInput
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.semantics.contentDescription
import androidx.compose.ui.semantics.semantics
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.IntOffset
import androidx.compose.ui.unit.dp
import eu.kanade.tachiyomi.data.tts.AutoReadEngine
import mihon.domain.ocr.model.OcrBoundingBox
import kotlin.math.roundToInt

/**
 * Значок 🔊 над репликами (баблами) читалки.
 *
 * Один-единственный бейдж: пока TTS озвучивает реплику ([isSpeaking] — true),
 * показывается ровно ОДИН значок у текущего бабла (справа сверху от его рамки),
 * а не россыпь значков по странице. Когда озвучка не идёт, значков на данных
 * нет — остаётся только перетаскиваемый значок для ручной озвучки реплики.
 *
 * Координаты баблов — нормализованные 0..1 относительно СТРАНИЦЫ, а страница
 * занимает лишь часть окна (поля сверху/снизу у манги, по бокам у вебтуна).
 * Поэтому [imageRect] — прямоугольник страницы в долях окна (его отдаёт
 * `Viewer.displayedPageRect()`): раньше координаты умножались на размер всего
 * окна, и значок уезжал с реплики. Без [imageRect] (например в браузере)
 * поведение прежнее — вся область.
 *
 * Если текущую реплику найти не удалось, значок НЕ рисуется: жёсткая привязка
 * к углу окна выглядела для читателя как «значок прыгает по странице».
 */
@Composable
fun OcrBubbleVoiceOverlay(
    regions: List<AutoReadEngine.FrameRegion>,
    onSpeakRegion: (text: String, index: Int) -> Unit,
    modifier: Modifier = Modifier,
    perBubble: Boolean = true,
    draggable: Boolean = true,
    iconColor: Color = Color(0xFF00E5FF),
    isSpeaking: Boolean = false,
    imageRect: android.graphics.RectF? = null,
) {
    if (regions.isEmpty()) return
    BoxWithConstraints(
        modifier = modifier.fillMaxSize().semantics { contentDescription = "Бейдж озвучки реплик" },
    ) {
        val maxW = maxWidth
        val maxH = maxHeight
        val iconSize = 30.dp

        if (isSpeaking) {
            // ЕДИНЫЙ бейдж: один индикатор у реплики, которую TTS озвучивает
            // сейчас. Нет реплики или нет её рамки — не рисуем ничего.
            val current = regions.firstOrNull { it.state == AutoReadEngine.FrameRegion.State.CURRENT }
            val currentIndex = current?.let { regions.indexOf(it) } ?: -1
            val anchor = remember(current, imageRect, maxW, maxH) {
                current
                    ?.takeIf { it.text.isNotBlank() && it.box.isValidForIcon() }
                    ?.box
                    ?.iconAnchor(imageRect, maxW, maxH, iconSize)
            }
            if (current != null && currentIndex >= 0 && anchor != null) {
                Box(
                    modifier = Modifier
                        .offset(x = anchor.x, y = anchor.y)
                        .size(iconSize)
                        .pointerInput(currentIndex, current.text, onSpeakRegion) {
                            detectTapGestures { onSpeakRegion(current.text, currentIndex) }
                        }
                        .semantics {
                            contentDescription =
                                "Озвучить реплику ${current.index}: ${current.text.take(30)}"
                        },
                    contentAlignment = Alignment.Center,
                ) {
                    SpeakerBadge(color = iconColor, size = iconSize)
                }
            }
        } else if (draggable) {
            // Не звучит — только перетаскиваемый значок для ручной озвучки.
            DraggableSpeakIcon(
                regions = regions,
                onSpeakRegion = onSpeakRegion,
                accent = iconColor,
                imageRect = imageRect,
            )
        }
    }
}

/** Круглая кнопка-значок озвучки. */
@Composable
private fun SpeakerBadge(color: Color, size: Dp) {
    Surface(
        shape = CircleShape,
        color = color.copy(alpha = 0.85f),
        contentColor = Color.Black,
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.4f)),
        modifier = Modifier.size(size),
    ) {
        Box(modifier = Modifier.size(size), contentAlignment = Alignment.Center) {
            Icon(
                Icons.Outlined.RecordVoiceOver,
                contentDescription = null,
                modifier = Modifier.padding(size / 4f),
            )
        }
    }
}

/** Один перетаскиваемый значок: при отпускании привязывается к ближайшему баблу. */
@Composable
private fun DraggableSpeakIcon(
    regions: List<AutoReadEngine.FrameRegion>,
    onSpeakRegion: (String, Int) -> Unit,
    accent: Color,
    imageRect: android.graphics.RectF?,
) {
    var posX by remember { mutableStateOf(0f) }
    var posY by remember { mutableStateOf(0f) }
    var placed by remember { mutableStateOf(false) }
    val density = LocalDensity.current

    BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
        val pxW = with(density) { maxWidth.toPx() }
        val pxH = with(density) { maxHeight.toPx() }

        Box(
            modifier = Modifier
                .offset { if (!placed) IntOffset.Zero else IntOffset(posX.roundToInt(), posY.roundToInt()) }
                .size(36.dp)
                .pointerInput(pxW, pxH, regions, onSpeakRegion, imageRect) {
                    detectDragGestures(
                        onDragStart = { placed = true },
                        onDrag = { change, drag ->
                            change.consume()
                            posX = (posX + drag.x).coerceIn(0f, pxW)
                            posY = (posY + drag.y).coerceIn(0f, pxH)
                        },
                        onDragEnd = {
                            val target = regions
                                .filter { it.text.isNotBlank() && it.box.isValidForIcon() }
                                .minByOrNull { r ->
                                    // Расстояние до центра бабла считаем в тех же
                                    // координатах, где лежит значок, иначе он
                                    // притягивается не к тому тексту.
                                    val dx = r.box.pageCenterX(imageRect) * pxW - (posX + 18f)
                                    val dy = r.box.pageCenterY(imageRect) * pxH - (posY + 18f)
                                    dx * dx + dy * dy
                                }
                            if (target != null) {
                                val idx = regions.indexOf(target)
                                onSpeakRegion(target.text, idx)
                            }
                        },
                    )
                },
            contentAlignment = Alignment.Center,
        ) {
            SpeakerBadge(color = accent, size = 36.dp)
        }
    }
}

/** Положение левого верхнего угла значка относительно области композиции. */
private data class IconAnchor(val x: Dp, val y: Dp)

/**
 * Куда поставить значок для бабла.
 *
 * [imageRect] — прямоугольник страницы в долях (0..1) области: рамка реплики
 * откладывается внутри страницы, а не от краёв окна.
 */
private fun OcrBoundingBox.iconAnchor(
    imageRect: android.graphics.RectF?,
    maxWidth: Dp,
    maxHeight: Dp,
    iconSize: Dp,
): IconAnchor {
    val pageLeft = imageRect?.left ?: 0f
    val pageTop = imageRect?.top ?: 0f
    val pageWidth = pageWidthFraction(imageRect)
    val pageHeight = pageHeightFraction(imageRect)
    val leftDp = (pageLeft + left * pageWidth) * maxWidth.value
    val topDp = (pageTop + top * pageHeight) * maxHeight.value
    val widthDp = (right - left) * pageWidth * maxWidth.value
    return IconAnchor(
        x = leftDp.dp + widthDp.dp - iconSize,
        y = topDp.dp - iconSize / 3f,
    )
}

/** Центр бокса по X в долях области (0..1) — с учётом прямоугольника страницы. */
private fun OcrBoundingBox.pageCenterX(imageRect: android.graphics.RectF?): Float =
    (imageRect?.left ?: 0f) + centerX() * pageWidthFraction(imageRect)

/** Центр бокса по Y в долях области (0..1) — с учётом прямоугольника страницы. */
private fun OcrBoundingBox.pageCenterY(imageRect: android.graphics.RectF?): Float =
    (imageRect?.top ?: 0f) + centerY() * pageHeightFraction(imageRect)

private fun pageWidthFraction(imageRect: android.graphics.RectF?): Float =
    (imageRect?.width() ?: 1f).coerceAtLeast(0.0001f)

private fun pageHeightFraction(imageRect: android.graphics.RectF?): Float =
    (imageRect?.height() ?: 1f).coerceAtLeast(0.0001f)

/** Центр нормализованного бокса (0..1). */
private fun OcrBoundingBox.centerX(): Float = (left + right) / 2f
private fun OcrBoundingBox.centerY(): Float = (top + bottom) / 2f

/** Размер рамки достаточно велик и лежит в пределах изображения. */
private fun OcrBoundingBox.isValidForIcon(): Boolean =
    left >= -0.001f && top >= -0.001f && right <= 1.001f && bottom <= 1.001f &&
        (right - left) > 0.02f && (bottom - top) > 0.01f

