private const val OCR_SCAN_MAX_EDGE_PORTRAIT = 2048
/** Кадры мельче этой стороны уравниваем вверх. */
private const val OCR_UPSCALE_BELOW_EDGE = 1000
/** Больше чем в 1.5 раза мелкий кадр не растягиваем (время OCR). */
