                    eu.kanade.tachiyomi.data.ocr.OcrModelDownloader.downloadPack(context, pack) { ok ->
                        refresh++
                        if (ok) modelPref.set(model)
                    }
                }
                else -> {
                    modelPref.set(model)
                    open = false
                }
            }
        },
    )
}
