            FrameResult.READ -> Unit
            FrameResult.BLOCKED -> {
                stopAutoReadLoop()
                return
            }
            FrameResult.NOT_READY -> {
                stopAutoReadLoopWith(FRAME_NOT_READY_MESSAGE)
                return
            }
            FrameResult.FAILED -> {
                stopAutoReadLoopWith("Кадр не прочитан — авточтение остановлено")
                return
            }
        }
